WITH eligible AS (SELECT s.* FROM stores s WHERE NOT EXISTS (SELECT 1 FROM inventory x WHERE x.store_id = s.id AND x.last_restock < s.opened_date)) SELECT DATE_TRUNC('QUARTER', opened_date) AS quarter_start, SIZE(COLLECT_SET(city)) AS num_cities, COUNT(*) FILTER (WHERE region = 'East') AS east_rows, APPROX_PERCENTILE(sqft, 0.9) AS sqft_p90, ROUND(AVG(sqft), 2) AS avg_sqft, BIT_AND(sqft) AS sqft_bit_and, APPROX_PERCENTILE(sqft, 0.95) AS sqft_p95 FROM eligible GROUP BY 1 HAVING SIZE(COLLECT_SET(city)) >= 1 ORDER BY num_cities NULLS LAST;
